from rich.text import Text
from rich.style import Style

def test_expand_tabs_preserves_style():
    text = Text("Hello\tWorld")
    text.stylize("red", 0, 6)  # "Hello\t" is red
    text.stylize("blue", 6, 11) # "World" is blue

    # Tab is at index 5. It should be red.
    # "Hello" (5 chars) + tab (1 char)
    # Tab stop at 8. 5 chars + 1 tab = 6 chars.
    # Need 8 - 6 = 2 more spaces.

    text.expand_tabs(tab_size=8)

    # "Hello" (5) + " " (1) + "  " (2) + "World" (5) = 13 chars
    # The tab was replaced by 3 spaces.
    # Indices 5, 6, 7 should be red.

    # Check if the spaces are red
    # We can check the spans of the resulting text
    for span in text._spans:
        if span.start <= 5 < span.end:
            assert span.style == Style("red")
        if span.start <= 6 < span.end:
            assert span.style == Style("red")
        if span.start <= 7 < span.end:
            assert span.style == Style("red")

    # "World" starts at index 8
    for span in text._spans:
        if span.start <= 8 < span.end:
            assert span.style == Style("blue")

if __name__ == "__main__":
    try:
        test_expand_tabs_preserves_style()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

